import 'dart:convert'; import 'dart:io'; void main() async { final httpClient = HttpClient(); try { final request = await httpClient.getUrl(Uri.parse('https://myharur.onrender.com/api/v1/community/chat/rooms/1/messages')); final response = await request.close(); final stringData = await response.transform(utf8.decoder).join(); final data = jsonDecode(stringData); print('Success: ' + data.length.toString() + ' messages'); } catch(e) { print('Error: ' + e.toString()); } }
